// Arma el aviso semanal: texto simple + versión HTML con tabla y botón.
const r = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const base = (p) => String(p).split('/').pop();
const dir = (p) => String(p).split('/').slice(0, -1).join(' › ');
const filas = (r.moved || []).slice(0, 20).map((m) => `
  <tr>
    <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827">
      <b>${esc(base(m.file))}</b><br><span style="color:#6b7280;font-size:12px">${esc(dir(m.file))}</span></td>
    <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;color:#047857;white-space:nowrap">${esc(m.keep)}</td>
  </tr>`).join('');
const mas = r.count > 20 ? `<p style="color:#6b7280;font-size:12px">… y ${r.count - 20} más. Están todas en el portal.</p>` : '';
const url = r.portal_url || 'http://127.0.0.1:8000';
const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;max-width:640px;margin:0 auto;color:#111827">
  <div style="background:#1e3a5f;color:#fff;padding:18px 22px;border-radius:10px 10px 0 0">
    <div style="font-size:12px;opacity:.8;letter-spacing:.04em">PORTAL DE DOCUMENTACIÓN · SERVELEC</div>
    <div style="font-size:20px;font-weight:600;margin-top:4px">Limpieza semanal</div>
  </div>
  <div style="border:1px solid #e5e7eb;border-top:0;padding:20px 22px;border-radius:0 0 10px 10px">
    <p style="font-size:15px;margin:0 0 14px">Hay <b>${r.count} archivo${r.count === 1 ? '' : 's'}</b> de revisiones anteriores para mandar a la carpeta <b>OBSOLETO</b>. Todavía no se movió nada.</p>
    <table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb">
      <thead><tr style="background:#f3f4f6">
        <th style="text-align:left;padding:8px 12px;font-size:12px;color:#6b7280">Se mueve a OBSOLETO</th>
        <th style="text-align:left;padding:8px 12px;font-size:12px;color:#6b7280">Se queda</th></tr></thead>
      <tbody>${filas}</tbody>
    </table>
    ${mas}
    <p style="margin:20px 0 6px"><a href="${esc(url)}" style="background:#1e3a5f;color:#fff;text-decoration:none;padding:10px 18px;border-radius:6px;font-size:14px;display:inline-block">Abrir el portal</a></p>
    <p style="color:#6b7280;font-size:12px;margin:10px 0 0">Para ejecutarla: Limpieza → Ejecutar. Solo Ingeniería y Sistemas pueden hacerlo.</p>
  </div>
</div>`;
const lista = (r.moved || []).slice(0, 15).map((m) => `• ${m.file}  (se queda ${m.keep})`).join('\n');
const texto = `Limpieza semanal: hay ${r.count} archivo(s) de revisiones viejas para mandar a OBSOLETO.\n\n${lista}\n\nPara ejecutarla: portal → Limpieza → Ejecutar. ${url}`;
return [{ json: { count: r.count, asunto: `Portal SERVELEC: limpieza semanal (${r.count} archivo${r.count === 1 ? '' : 's'})`, texto, html } }];
